'use strict';
// Builds real two-color GIF89a files entirely from generated bytes.

const TABLE = Buffer.from([0, 0, 0, 255, 255, 255]);

function imageData(pixels) {
  // Minimum code size 2 gives clear=4, EOI=5 and initial width=3 bits. Emit clear
  // before each zero pixel: the dictionary resets before it can grow, so every
  // code (including EOI) stays three bits wide. GIF packs these bits LSB-first.
  const data = Buffer.alloc(Math.ceil((pixels * 2 + 1) * 3 / 8));
  let bit = 0;
  function code(value) {
    for (let n = 0; n < 3; n++, bit++) data[bit >> 3] |= ((value >> n) & 1) << (bit & 7);
  }
  for (let n = 0; n < pixels; n++) { code(4); code(0); }
  code(5);
  const blocks = [Buffer.from([2])];
  for (let pos = 0; pos < data.length; pos += 255) {
    const part = data.subarray(pos, pos + 255);
    blocks.push(Buffer.from([part.length]), part);
  }
  blocks.push(Buffer.from([0]));
  return Buffer.concat(blocks);
}

// Omit delayCs and transparentIndex together to generate a frame without a GCE.
function gif({ width = 4, height = 3, frames = [{}], loop, globalTable = true } = {}) {
  const header = Buffer.alloc(13);
  header.write('GIF89a', 0, 'latin1');
  header.writeUInt16LE(width, 6);
  header.writeUInt16LE(height, 8);
  header[10] = globalTable ? 0x80 : 0;
  const parts = [header];
  if (globalTable) parts.push(TABLE);
  if (loop !== undefined) {
    const app = Buffer.from([0x21, 0xff, 11, ...Buffer.from('NETSCAPE2.0'), 3, 1, 0, 0, 0]);
    app.writeUInt16LE(loop, 16);
    parts.push(app);
  }
  const data = imageData(width * height);
  for (const { delayCs, transparentIndex } of frames) {
    if (delayCs !== undefined || transparentIndex !== undefined) {
      const gce = Buffer.from([0x21, 0xf9, 4, transparentIndex === undefined ? 0 : 1, 0, 0, transparentIndex ?? 0, 0]);
      gce.writeUInt16LE(delayCs ?? 0, 4);
      parts.push(gce);
    }
    const descriptor = Buffer.alloc(10);
    descriptor[0] = 0x2c;
    descriptor.writeUInt16LE(width, 5);
    descriptor.writeUInt16LE(height, 7);
    descriptor[9] = globalTable ? 0 : 0x80;
    parts.push(descriptor);
    if (!globalTable) parts.push(TABLE);
    parts.push(data);
  }
  parts.push(Buffer.from([0x3b]));
  return Buffer.concat(parts);
}

module.exports = { gif };
